def newman_prime(n):
  """
  Finds the nth Newman-Shanks-Williams prime number.

  Args:
      n: The index of the desired prime number (1-based indexing).

  Returns:
      The nth Newman-Shanks-Williams prime number.
  """
  def is_prime(num):
    if num <= 1:
      return False
    for i in range(2, int(num**0.5) + 1):
      if num % i == 0:
        return False
    return True

  count = 0
  num = 2
  while count < n:
    if is_prime(num):
      if is_prime(num + 1):
        count += 1
    num += 1
  return num - 1
```

